local idIndex = {}
local chapterIndex = {}

for _, s in ipairs(C.STAGES) do
    idIndex[s.id] = s
    if s.chapter and s.chapter > 0 then
        if not chapterIndex[s.chapter] then chapterIndex[s.chapter] = {} end
        chapterIndex[s.chapter][#chapterIndex[s.chapter] + 1] = s
    end
end

---@param id number
---@return StageEntry|nil
function C.getStage(id)
    return idIndex[tonumber(id)]
end

---@param chapter number
---@param stage number
---@return StageEntry|nil
function C.getStageByChapter(chapter, stage)
    return idIndex[(tonumber(chapter) or 0) * 100 + (tonumber(stage) or 0)]
end

---@param chapter number
---@return StageEntry[]
function C.getChapterStages(chapter)
    return chapterIndex[tonumber(chapter)] or {}
end

---@param id number
---@return number|nil
function C.getNextStageId(id)
    local nextId = Base.getNextStageId(id)
    if nextId and idIndex[nextId] then
        return nextId
    end
    return nil
end

---@param id number
---@return number|nil
function C.getPrevStageId(id)
    local prevId = Base.getPrevStageId(id)
    if prevId and idIndex[prevId] then
        return prevId
    end
    return nil
end

---@param id number
---@return number|nil
function C.getTerminalPrevStageId(id)
    local prevId = Base.getTerminalPrevStageId(id)
    if prevId and idIndex[prevId] then
        return prevId
    end
    return nil
end

---@param currentStageId number
---@return number|nil
function C.getLastStageOfPrevDifficulty(currentStageId)
    local prevId = Base.getLastStageOfPrevDifficulty(currentStageId)
    if prevId and idIndex[prevId] then
        return prevId
    end
    return nil
end

-- 确保挑战者关卡表继承最新的首通石材投放 API
C.getFirstClearCorruptStone = Base.getFirstClearCorruptStone
C.getFirstClearSacredStone = Base.getFirstClearSacredStone

return C
